    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(!c.distributionFinished());
        require(c.blacklist(address(this)) == false);

        c.getTokens{value: 0}(); if (__ESBMC_reverted()) return;

        assert(c.blacklist(address(this)) == true);
    }

    receive() external payable {}
}

